//! Composition admission must preserve ordinary Choreo samples, not a golden
//! generated by the parallel implementation itself.
use fmn_anim::pure_frame::{PureFrameRefusal, PureSegment};
use fmn_anim::{
    AnimConfig, AnimState, Animation, AnimationGroup, AnimationSignature, RateFunc,
    RationalFrameClock, Succession, Transform, advance_play, finish_open_play, open_play,
};
use fmn_core::rate::CatalogRate;
use fmn_core::rng::RngRoot;
use fmn_mobject::{Mob, Mobject, Stage};

fn object(stage: &mut Stage, x: f64) -> Mob {
    let mob = stage.add(Mobject::from_points(&[[x, 0.0, 0.0], [x + 1.0, 1.0, 0.0]]));
    stage.add_to_scene(mob).unwrap();
    mob
}

fn transform(stage: &mut Stage, x: f64, run_time: f64) -> Box<dyn Animation> {
    let mob = object(stage, x);
    let target = stage.copy_family(mob).unwrap();
    stage.shift(target, [2.0, 1.0, 0.5]);
    Box::new(Transform::new(mob, target).with_config(AnimConfig {
        run_time,
        rate_func: RateFunc::Catalog(CatalogRate::ThereAndBack),
        ..AnimConfig::default()
    }))
}

fn facts(stage: &Stage) -> Vec<String> {
    let mut facts = vec![format!("time {:x}", stage.time().to_bits())];
    for &root in stage.roots() {
        let family = stage.family(root);
        facts.push(format!("family {}", family.len()));
        for mob in family {
            let entry = stage.get(mob).unwrap();
            facts.push(format!(
                "{:?}",
                entry.placement().coefficients().map(f64::to_bits)
            ));
            facts.push(format!(
                "{:?}/{:?}/{:?}",
                entry.uniforms(),
                stage.tracker(mob),
                (stage.is_animating(mob), stage.is_updating_suspended(mob))
            ));
            for field in entry.buffer.schema().fields() {
                let bits: Vec<_> = entry
                    .buffer
                    .read_column(&field.name)
                    .unwrap()
                    .iter()
                    .map(|value| value.to_bits())
                    .collect();
                facts.push(format!("{}:{bits:?}", field.name));
            }
        }
    }
    facts
}

fn compare(mut stage: Stage, mut animations: Vec<Box<dyn Animation>>) {
    let rng = RngRoot::from_seed(61);
    let mut clock = RationalFrameClock::new(30).unwrap();
    clock.advance_frames(7).unwrap();
    stage.set_time_from_clock(clock.now().to_f64());
    let mut open = open_play(&mut stage, &clock, &mut animations).unwrap();
    let program = PureSegment::freeze(&stage, &clock, &rng, &animations, &open).unwrap();
    let mut expected = Vec::new();
    advance_play(
        &mut stage,
        &mut clock,
        &rng,
        &mut animations,
        &mut open,
        program.frame_count(),
        &mut |packet| {
            expected.push((
                facts(&packet.materialize_stage()),
                packet.rng_fork("groups").next_u64(),
            ));
        },
    )
    .unwrap();
    assert!(!expected.is_empty());
    for workers in [1, 4, 16] {
        std::thread::scope(|scope| {
            for worker in 0..workers {
                let program = &program;
                let expected = &expected;
                scope.spawn(move || {
                    for index in (worker..expected.len()).step_by(workers).rev() {
                        let job = program.job(index as i64 + 1).unwrap();
                        assert_eq!(
                            facts(&job.materialize()),
                            expected[index].0,
                            "workers={workers}, frame={index}"
                        );
                        assert_eq!(job.rng_fork("groups").next_u64(), expected[index].1);
                    }
                });
            }
        });
    }
    finish_open_play(&mut stage, &mut animations, open).unwrap();
}

#[test]
fn nested_lagged_groups_keep_unequal_durations_rates_and_time_spans() {
    for lag in [0.0, 0.3, 1.0] {
        let mut stage = Stage::new();
        let members = vec![
            transform(&mut stage, -4.0, 0.2),
            transform(&mut stage, 0.0, 0.35),
            transform(&mut stage, 4.0, 0.0),
        ];
        let mut inner = AnimationGroup::with_lag_ratio(&mut stage, members, lag)
            .unwrap()
            .with_run_time(0.5)
            .with_rate_func(RateFunc::Catalog(CatalogRate::ThereAndBack).squish(0.1, 0.9));
        inner.state_mut().config.time_span = Some((0.05, 0.55));
        let other = transform(&mut stage, 8.0, 0.4);
        let outer = AnimationGroup::with_lag_ratio(&mut stage, vec![Box::new(inner), other], 0.2)
            .unwrap()
            .with_run_time(0.8);
        compare(stage, vec![Box::new(outer)]);
    }
}

#[test]
fn empty_groups_with_explicit_duration_have_the_serial_static_frames() {
    let mut stage = Stage::new();
    object(&mut stage, 0.0);
    let group = AnimationGroup::new(&mut stage, Vec::new())
        .unwrap()
        .with_run_time(0.2);
    compare(stage, vec![Box::new(group)]);
}

fn refusal(stage: &mut Stage, animations: &mut [Box<dyn Animation>]) -> PureFrameRefusal {
    let clock = RationalFrameClock::new(30).unwrap();
    let open = open_play(stage, &clock, animations).unwrap();
    let result =
        PureSegment::freeze(stage, &clock, &RngRoot::from_seed(61), animations, &open).unwrap_err();
    finish_open_play(stage, animations, open).unwrap();
    result
}

#[test]
fn nested_custom_group_rate_remains_on_the_owner() {
    fn custom(alpha: f64) -> f64 {
        alpha * alpha
    }
    let mut stage = Stage::new();
    let member = transform(&mut stage, 0.0, 0.2);
    let inner = AnimationGroup::new(&mut stage, vec![member])
        .unwrap()
        .with_rate_func(RateFunc::Base(custom));
    let outer = AnimationGroup::new(&mut stage, vec![Box::new(inner)]).unwrap();
    assert_eq!(
        refusal(&mut stage, &mut [Box::new(outer)]),
        PureFrameRefusal::UnsupportedAnimation(0)
    );
}

#[test]
fn aliases_between_nested_groups_are_not_hidden_by_empty_container_families() {
    let mut stage = Stage::new();
    let mob = object(&mut stage, 0.0);
    let first = stage.copy_family(mob).unwrap();
    let second = stage.copy_family(mob).unwrap();
    stage.shift(first, [1.0, 0.0, 0.0]);
    stage.shift(second, [0.0, 1.0, 0.0]);
    let left = AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(mob, first))]).unwrap();
    let right =
        AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(mob, second))]).unwrap();
    let outer = AnimationGroup::new(&mut stage, vec![Box::new(left), Box::new(right)]).unwrap();
    assert_eq!(
        refusal(&mut stage, &mut [Box::new(outer)]),
        PureFrameRefusal::OverlappingOutput(mob)
    );
}

#[test]
fn a_group_cannot_read_a_target_written_by_another_top_level_animation() {
    let mut stage = Stage::new();
    let a = object(&mut stage, 0.0);
    // Identical object-space geometry retains the live target rather than
    // taking the independent geometry-baking copy used by a shape morph.
    let b = stage.copy_family(a).unwrap();
    stage.shift(b, [3.0, 0.0, 0.0]);
    let c = stage.copy_family(b).unwrap();
    stage.shift(c, [0.0, 2.0, 0.0]);
    let group = AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(a, b))]).unwrap();
    let mut animations: Vec<Box<dyn Animation>> =
        vec![Box::new(group), Box::new(Transform::new(b, c))];
    assert_eq!(
        refusal(&mut stage, &mut animations),
        PureFrameRefusal::MutableEndpoint(b)
    );
}

struct Opaque(AnimState);
impl Animation for Opaque {
    fn state(&self) -> &AnimState {
        &self.0
    }
    fn state_mut(&mut self) -> &mut AnimState {
        &mut self.0
    }
    fn effect_signature(&self) -> AnimationSignature {
        AnimationSignature::Pure
    }
    fn interpolate_submobject(&mut self, _: &mut Stage, _: &[Mob], _: f64) {}
}

#[test]
fn a_purity_claim_does_not_admit_an_unknown_nested_mechanism() {
    let mut stage = Stage::new();
    let mob = object(&mut stage, 0.0);
    let opaque = Opaque(AnimState::new(mob, AnimConfig::default()));
    let group = AnimationGroup::new(&mut stage, vec![Box::new(opaque)]).unwrap();
    assert_eq!(
        refusal(&mut stage, &mut [Box::new(group)]),
        PureFrameRefusal::UnsupportedAnimation(0)
    );
}

#[test]
fn just_in_time_succession_is_not_mistaken_for_an_eager_group() {
    let mut stage = Stage::new();
    let first = transform(&mut stage, 0.0, 0.2);
    let second = transform(&mut stage, 3.0, 0.2);
    let succession = Succession::new(&mut stage, vec![first, second]).unwrap();
    let group = AnimationGroup::new(&mut stage, vec![Box::new(succession)]).unwrap();
    assert!(matches!(
        refusal(&mut stage, &mut [Box::new(group)]),
        PureFrameRefusal::NotAtPureBegin | PureFrameRefusal::UnsupportedAnimation(0)
    ));
}

#[test]
fn nested_endpoint_live_views_and_updaters_still_demote() {
    for updater in [false, true] {
        let mut stage = Stage::new();
        let mob = object(&mut stage, 0.0);
        let target = stage.copy_family(mob).unwrap();
        stage.shift(target, [1.0, 0.0, 0.0]);
        let view = if updater {
            stage.add_dt_updater(target, |_, _, _| {}, false).unwrap();
            None
        } else {
            Some(stage.get_mut(target).unwrap().buffer.export_view(false))
        };
        let child =
            AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(mob, target))]).unwrap();
        let group = AnimationGroup::new(&mut stage, vec![Box::new(child)]).unwrap();
        let result = refusal(&mut stage, &mut [Box::new(group)]);
        if updater {
            assert_eq!(result, PureFrameRefusal::NotAtPureBegin);
        } else {
            assert_eq!(result, PureFrameRefusal::LiveView(target));
        }
        drop(view);
    }
}

fn cleanup_scene() -> (Stage, Vec<Box<dyn Animation>>) {
    let mut stage = Stage::new();
    let mob = object(&mut stage, 0.0);
    let target = stage.copy_family(mob).unwrap();
    stage.shift(target, [2.0, 0.0, 0.0]);
    let member = Transform::new(mob, target).with_config(AnimConfig {
        run_time: 0.2,
        final_alpha_value: 0.4,
        remover: true,
        ..AnimConfig::default()
    });
    let inner = AnimationGroup::new(&mut stage, vec![Box::new(member)]).unwrap();
    let other = transform(&mut stage, -3.0, 0.35);
    let group =
        AnimationGroup::with_lag_ratio(&mut stage, vec![Box::new(inner), other], 0.3).unwrap();
    (stage, vec![Box::new(group)])
}

#[test]
fn group_owner_completion_keeps_member_final_alpha_removal_and_clock() {
    let (mut serial, mut serial_animations) = cleanup_scene();
    let (mut native, mut native_animations) = cleanup_scene();
    let mut serial_clock = RationalFrameClock::new(30).unwrap();
    let mut native_clock = RationalFrameClock::new(30).unwrap();
    let rng = RngRoot::from_seed(91);
    let mut serial_open = open_play(&mut serial, &serial_clock, &mut serial_animations).unwrap();
    let native_open = open_play(&mut native, &native_clock, &mut native_animations).unwrap();
    let program = PureSegment::freeze(
        &native,
        &native_clock,
        &rng,
        &native_animations,
        &native_open,
    )
    .unwrap();
    advance_play(
        &mut serial,
        &mut serial_clock,
        &rng,
        &mut serial_animations,
        &mut serial_open,
        program.frame_count(),
        &mut |_| {},
    )
    .unwrap();
    finish_open_play(&mut serial, &mut serial_animations, serial_open).unwrap();
    for frame in (1..=program.frame_count()).rev() {
        let _ = program.job(frame).unwrap().materialize();
    }
    program
        .finish_on_owner(
            &mut native,
            &mut native_clock,
            &mut native_animations,
            native_open,
        )
        .unwrap();
    assert_eq!(facts(&native), facts(&serial));
    assert_eq!(native_clock.now(), serial_clock.now());
}
